/**
 * `packages/mcp/src/assets.generated.ts` (DD-047, OQ-E3): what `render_chart` writes into a
 * standalone SVG, read from the sources at generation time so the server reads no file at run
 * time — the grounds' stylesheet, minified, and the EB Garamond regular face for `embedFonts`.
 * Regenerated by `generate` and diffed by `check`, as the catalog is.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '../..');
export const ASSETS_FILE = join(ROOT, 'packages/mcp/src/assets.generated.ts');
const STYLES = join(ROOT, 'packages/grounds/src/styles.css');
const FACE = join(ROOT, 'packages/fonts/files/eb-garamond-latin-400-normal.woff2');

/** Comments out, whitespace collapsed; spaces inside values (`Georgia, serif`) kept. */
export function minifyCss(css: string): string {
  return css
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\s+/g, ' ')
    .replace(/\s*([{};])\s*/g, '$1')
    .replace(/:\s+/g, ':')
    .replace(/;}/g, '}')
    .trim();
}

export function assetsSource(): string {
  const css = minifyCss(readFileSync(STYLES, 'utf8'));
  const face = readFileSync(FACE).toString('base64');
  return [
    '// Generated by tools/agent-catalog (pnpm --filter @silverpoint/agent-catalog generate). Do not edit.',
    '',
    '/** `@silverpoint/grounds` styles.css, minified: the ground rules a standalone SVG carries (DD-047). */',
    `export const GROUND_CSS = ${JSON.stringify(css)};`,
    '',
    '/** EB Garamond 400, latin subset, WOFF2 in base64 (`@silverpoint/fonts`, OFL-1.1): `embedFonts` (OQ-E3). */',
    `export const EB_GARAMOND_400 = ${JSON.stringify(face)};`,
    '',
  ].join('\n');
}
